# Mots fréquents dans les textes : dans le lexique, mais pas soulignés partout (règle : on ne souligne que les mots propres à la foi).
NON_SOULIGNES = ['foi', 'esperance', 'charite', 'seigneur', 'christ', 'eglise', 'ame', 'ciel', 'enfer', 'fidele', 'disciple', 'ange', 'louange',
  'mariage', 'noel', 'pretre', 'pape', 'eveque', 'conscience', 'conversion', 'miracle', 'saintete', 'commandements', 'vertus', 'paroisse',
  'benediction', 'meditation', 'demon', 'memoire', 'tradition', 'alliance', 'retraite', 'icone', 'octave', 'quete', 'passion', 'salut', 'angelus',
  'ferie', 'bienheureux', 'concile', 'religieux', 'dizaine', 'revelation']

def formes(mot, extra):
    out = [mot]
    if mot[:1].lower() + mot[1:] != mot and ' ' not in mot[:1]: out.append(mot[:1].lower() + mot[1:])
    for e in extra:
        if e not in out: out.append(e)
    return out

if __name__ == '__main__':
    p = os.path.join(R, 'lexique.json'); d = json.load(open(p))
    ids = {m['id'] for m in d['mots']}
    nouveaux = [x for x in M if x[0] not in ids]
    for i, fr, es, en in nouveaux:
        e = {'id': i, 'mot': fr[0], 'formes': formes(fr[0], fr[2]), 'def': fr[1]}
        if i in NON_SOULIGNES: e['souligne'] = False
        d['mots'].append(e)
    open(p, 'w').write(json.dumps(d, ensure_ascii=False, indent=2) + '\n')
    for l, k in (('es', 2), ('en', 3)):
        p = os.path.join(R, 'i18n', l + '.json'); d = json.load(open(p))
        for x in nouveaux: d['lexique']['mots'].append({'id': x[0], 'mot': x[k][0], 'formes': formes(x[k][0], x[k][2]), 'def': x[k][1]})
        open(p, 'w').write(json.dumps(d, ensure_ascii=False, indent=1) + '\n')
    print(len(nouveaux), 'mots ajoutés')
